var stitems = {};
var product_unit_conversions = {};
if (typeof product_units === 'undefined') { var product_units = {}; }

// all_units = unit_id => unit_name (from PHP)
var all_units = all_units || {};

// Add item to stock transfer
function add_transfer_item(item) {
    var item_id = item.id;
    var product_id = item.row.id;

    if (item.units) product_units[product_id] = item.units;
    if (item.unit_conversions) product_unit_conversions[product_id] = item.unit_conversions;

    if (item.row.is_dual_unit == 1) {
        item.row.primary_qty = item.row.primary_qty || 0;
        item.row.secondary_qty = item.row.secondary_qty || 0;
        item.row.primary_unit = item.row.primary_unit || item.row.base_unit_id;
        item.row.secondary_unit = item.row.secondary_unit || item.row.secondary_unit_id;
    } else {
        item.row.qty = item.row.qty || 1;
        item.row.unit_id = item.row.unit_id || item.row.base_unit_id;
    }

    stitems[item_id] = item;
    store('stitems', JSON.stringify(stitems));
    loadTransferItems();
}

// Render transfer items
function loadTransferItems() {
    if (get('stitems')) {
        stitems = JSON.parse(get('stitems'));
        $("#itemsTable tbody").empty();

        $.each(stitems, function () {
            var item = this;
            var item_id = item.id;
            var product_id = item.row.id;

            var row_no = new Date().getTime();
            var newTr = $('<tr id="' + row_no + '" data-item-id="' + item_id + '" data-id="' + product_id + '"></tr>');
            var tr_html = '<td><input type="hidden" name="product_id[]" value="' + product_id + '">' +
                          item.row.name + ' (' + item.row.code + ')</td>';

            if (item.row.is_dual_unit == 1) {
                var primaryOptions = '';
                var secondaryOptions = '';

                if (product_units[product_id]) {
                    $.each(product_units[product_id], function (id, name) {
                        var selected_primary = (item.row.primary_unit == id) ? "selected" : "";
                        var selected_secondary = (item.row.secondary_unit == id) ? "selected" : "";
                        primaryOptions += '<option value="' + id + '" ' + selected_primary + '>' + name + '</option>';
                        secondaryOptions += '<option value="' + id + '" ' + selected_secondary + '>' + name + '</option>';
                    });
                }

                tr_html += '<td><input type="number" class="form-control primary_qty" name="primary_qty[]" value="' + item.row.primary_qty + '"></td>';
                tr_html += '<td><select name="primary_unit[]" class="form-control pos-unit">' + primaryOptions + '</select></td>';
                tr_html += '<td><input type="number" class="form-control secondary_qty" name="secondary_qty[]" value="' + item.row.secondary_qty + '"></td>';
                tr_html += '<td><select name="secondary_unit[]" class="form-control pos-unit">' + secondaryOptions + '</select></td>';

            } else {
                var unitOptions = '';
                if (product_units[product_id]) {
                    $.each(product_units[product_id], function (id, name) {
                        var selected = (item.row.unit_id == id) ? "selected" : "";
                        unitOptions += '<option value="' + id + '" ' + selected + '>' + name + '</option>';
                    });
                }

                tr_html += '<td><input type="number" class="form-control rquantity" name="quantity[]" value="' + item.row.qty + '"></td>';
                tr_html += '<td><select name="unit[]" class="form-control pos-unit">' + unitOptions + '</select></td>';
                tr_html += '<td>-</td><td>-</td>';
            }

            tr_html += '<td class="text-center"><i class="fa fa-trash tip pointer stdel" data-item-id="' + item_id + '"></i></td>';
            newTr.html(tr_html);
            $("#itemsTable").append(newTr);
        });
    }
}

// Quantity/unit change handler
$(document).on("change keyup", '.rquantity, .primary_qty, .secondary_qty, .pos-unit', function () {
    var row = $(this).closest('tr');
    var item_id = row.data('item-id');
    var product_id = row.data('id');

    if (row.find('.primary_qty').length) {
        stitems[item_id].row.primary_qty = parseFloat(row.find('.primary_qty').val()) || 0;
        stitems[item_id].row.secondary_qty = parseFloat(row.find('.secondary_qty').val()) || 0;
        stitems[item_id].row.primary_unit = row.find('select[name="primary_unit[]"]').val();
        stitems[item_id].row.secondary_unit = row.find('select[name="secondary_unit[]"]').val();
    } else {
        stitems[item_id].row.qty = parseFloat(row.find('.rquantity').val()) || 0;
        stitems[item_id].row.unit_id = row.find('select[name="unit[]"]').val();
    }

    store('stitems', JSON.stringify(stitems));
});

// Document ready
$(document).ready(function () {
    loadTransferItems();

    // Remove item
    $(document).on('click', '.stdel', function () {
        var row = $(this).closest('tr');
        var item_id = row.attr('data-item-id');
        delete stitems[item_id];
        row.remove();
        localStorage.setItem('stitems', JSON.stringify(stitems));
    });

    // Autocomplete
    $("#add_item").autocomplete({
        source: base_url + 'stocktransfers/suggestions',
        minLength: 1,
        select: function (e, ui) {
            e.preventDefault();
            if (ui.item.id !== 0) {
                add_transfer_item(ui.item);
                $(this).val('');
            } else {
                bootbox.alert(lang.no_match_found);
            }
        }
    });
});
